const e = import.meta.env;

/**
 * Configuration lives in two files:
 * - `.env.local`: generated by Rayfin (`rayfin up` / `rayfin env`). Hosting of the app.
 * - `.env`: written by the deployment script or by hand from `.env.example`. MSAL registration and optional defaults.
 */
export const env = {
  msalClientId: e.VITE_MSAL_CLIENT_ID ?? '',
  msalTenantId: e.VITE_MSAL_TENANT_ID || e.VITE_FABRIC_TENANT_ID || 'organizations',
  defaultWorkspaceId: e.VITE_DEFAULT_WORKSPACE_ID ?? '',
  warnWorkspaces: (e.VITE_WARN_WORKSPACES ?? '').split(',').map((s: string) => s.trim().toLowerCase()).filter(Boolean),
  fabricPortalUrl: e.VITE_FABRIC_PORTAL_URL || 'https://app.fabric.microsoft.com',
  demo: (e.VITE_DEMO_MODE ?? '').toLowerCase() === 'true',
};

/** What is missing to work against real Fabric. Empty = ready. */
export function missingConfig(): string[] {
  if (env.demo) return [];
  const missing: string[] = [];
  if (!env.msalClientId || env.msalClientId.startsWith('<')) missing.push('VITE_MSAL_CLIENT_ID');
  return missing;
}
